// Value: protects=fixedSequence stops at the first failing step, never evaluates later steps and reports the passing prefix; fails_when=a step after a failure is evaluated or the prefix includes a step past the stop; why_new=no test imported src/runner/stats/fixed-sequence.ts; seam=none; no_claim=none beyond protects
// Generated by gstack /ship (U2 ship gate).
import { describe, expect, test } from "bun:test";
import { fixedSequence, type SequenceStep } from "../../src/runner/stats/fixed-sequence.ts";

const step = (id: string, pass: boolean, calls: string[]): SequenceStep<string> => ({ id, evaluate: () => { calls.push(id); return { pass, detail: id }; } });

describe("fixedSequence", () => {
  test("every step passes: all are tested and the prefix is the whole sequence", () => {
    const calls: string[] = [];
    const r = fixedSequence([step("a", true, calls), step("b", true, calls), step("c", true, calls)]);
    expect(calls).toEqual(["a", "b", "c"]);
    expect(r.results.map(x => x.status)).toEqual(["pass", "pass", "pass"]);
    expect(r.longest_passing_prefix).toEqual(["a", "b", "c"]);
    expect(r.stopped_at).toBeNull();
  });

  test("a middle failure stops the sequence and later steps are never evaluated", () => {
    const calls: string[] = [];
    const r = fixedSequence([step("a", true, calls), step("b", false, calls), step("c", true, calls)]);
    expect(calls).toEqual(["a", "b"]);
    expect(r.results.map(x => x.status)).toEqual(["pass", "fail", "not_tested"]);
    expect(r.results[1].detail).toBe("b");
    expect(r.results[2].detail).toBeUndefined();
    expect(r.results[2].reason).toContain("b failed earlier");
    expect(r.longest_passing_prefix).toEqual(["a"]);
    expect(r.stopped_at).toBe("b");
  });

  test("a first-step failure leaves an empty prefix; an empty sequence passes vacuously", () => {
    const calls: string[] = [];
    const r = fixedSequence([step("a", false, calls), step("b", true, calls)]);
    expect(calls).toEqual(["a"]);
    expect(r.longest_passing_prefix).toEqual([]);
    expect(r.stopped_at).toBe("a");
    expect(fixedSequence([])).toEqual({ results: [], longest_passing_prefix: [], stopped_at: null });
  });
});
